#!/usr/bin/env bash
# Installed outside releases; forced command for the dedicated Actions SSH key.
set -euo pipefail
umask 077
if [[ ! ${SSH_ORIGINAL_COMMAND:-} =~ ^deploy\ ([a-f0-9]{40})$ ]]; then
  echo 'Only deploy <commit SHA> is accepted.' >&2
  exit 2
fi
revision=${BASH_REMATCH[1]}
exec 9>/home/pi/.aibooking-deploy.lock
flock -w 600 9
release=/home/pi/aibooking-releases/$revision
mkdir -p "$release"
# The archive is generated by git archive in the trusted main-branch workflow.
tar --extract --file=- --directory="$release" --no-same-owner --no-same-permissions
cd "$release"
test -f Dockerfile && test -f compose.pi.yaml
compose=(docker compose --env-file /home/pi/aibooking/.env -p aibooking -f "$release/compose.pi.yaml")
previous=$(docker inspect --format '{{.Image}}' aibooking-app-1 2>/dev/null || true)
"${compose[@]}" build app
rollback() {
  if [[ -n $previous ]]; then
    printf 'services:\n  app:\n    image: %s\n' "$previous" > "$release/rollback.yaml"
    "${compose[@]}" -f "$release/rollback.yaml" up -d --no-build --no-deps app
  fi
}
if ! "${compose[@]}" up -d --no-build --no-deps --wait --wait-timeout 90 app; then
  rollback
  exit 1
fi
if ! curl -fsS --retry 3 --retry-delay 2 http://127.0.0.1:3090/api/status; then
  rollback
  exit 1
fi
printf '%s\n' "$revision" > /home/pi/aibooking-current-revision
ln -sfn "$release" /home/pi/aibooking-current
printf '\nDeployed %s\n' "$revision"
